import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import { NgForm } from '@angular/forms';
import { Router } from '@angular/router';
import { CartItem } from 'src/app/model/CartItem';
import { CartService } from 'src/app/services/cart.service';

@Component({
  selector: 'app-order-details',
  templateUrl: './order-details.component.html',
  styleUrls: ['./order-details.component.scss']
})
export class OrderDetailsComponent implements OnInit {
  cartItems: CartItem[] = [];

  order = {
    deliveryAddress: '',
    phone: '',
    paymentMode: '',
    totalAmount: 0,
    status: 'Pending',
    userId: 1, // Example, replace with actual logged-in user ID
    orderDate: new Date().toISOString().split('T')[0] // yyyy-mm-dd
  };

  constructor(
    private cartService: CartService,
    private http: HttpClient,
    private router: Router
  ) { }

  ngOnInit(): void {
    this.loadCartItems();
  }

  loadCartItems() {
    this.cartService.getCartItems().subscribe(items => {
      this.cartItems = items;
      console.log('Cart items:', this.cartItems);
    });
  }

  getTotalAmount(): number {
    return this.cartItems.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
  }

  placeOrder(form: NgForm) {
    if (form.invalid) return;

    const orderPayload = {
      userId: this.order.userId,
      orderDate: this.order.orderDate,
      deliveryAddress: this.order.deliveryAddress,
      totalAmount: this.getTotalAmount(),
      status: this.order.status,
      orderProducts: this.cartItems.map(item => ({
        productId: item.product.productId, // ensure productId exists in CartItem
        quantity: item.quantity
      }))
    };

    console.log('Form data to send:', orderPayload);

    this.http.post('http://localhost:8080/api/orders', orderPayload)
      .subscribe({
        next: (response) => {
          console.log('Order placed successfully', response);
          // Optionally redirect to order success page
          this.router.navigate(['/order-success']);
        },
        error: (error: HttpErrorResponse) => console.error('Error placing order', error)
      });
  }
}
<div class="order-form-container">
  <h2>Order Details</h2>

  <!-- Cart Items Table -->
  <table class="table table-bordered" *ngIf="cartItems.length > 0">
    <thead>
      <tr>
        <th>Product</th>
        <th>Quantity</th>
        <th>Price (₹)</th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let item of cartItems">
        <td>{{ item.product.title }}</td>
        <td>{{ item.quantity }}</td>
        <td>{{ item.product.price * item.quantity }}</td>
      </tr>
      <tr>
        <td colspan="2"><strong>Total Amount</strong></td>
        <td><strong>{{ getTotalAmount() }}</strong></td>
      </tr>
    </tbody>
  </table>

  <!-- Order Form -->
  <form #orderForm="ngForm" (ngSubmit)="placeOrder(orderForm)">
    <!-- Address -->
    <div class="form-group">
      <label for="address">Shipping Address</label>
      <textarea id="address" name="addressLine" class="form-control" rows="3"
                required
                [(ngModel)]="orderFormModel.addressLine"
                #addressLine="ngModel"></textarea>
      <div class="text-danger" *ngIf="addressLine.invalid && addressLine.touched">
        Address is required.
      </div>
    </div>

    <!-- Contact Number -->
    <div class="form-group">
      <label for="phone">Contact Number</label>
      <input type="text" id="phone" name="phone" class="form-control"
             required
             pattern="^[0-9]{10}$"
             [(ngModel)]="orderFormModel.phone"
             #phone="ngModel">
      <div class="text-danger" *ngIf="phone.invalid && phone.touched">
        Contact number must be 10 digits.
      </div>
    </div>

    <!-- Payment Mode -->
    <div class="form-group">
      <label>Payment Mode</label>
      <div>
        <label>
          <input type="radio" name="paymentMode" value="Cash on Delivery"
                 required
                 [(ngModel)]="orderFormModel.paymentMode"
                 #paymentMode="ngModel"> Cash on Delivery
        </label>
      </div>
      <div>
        <label>
          <input type="radio" name="paymentMode" value="Credit/Debit Card"
                 [(ngModel)]="orderFormModel.paymentMode"> Credit/Debit Card
        </label>
      </div>
      <div>
        <label>
          <input type="radio" name="paymentMode" value="UPI"
                 [(ngModel)]="orderFormModel.paymentMode"> UPI
        </label>
      </div>
      <div class="text-danger" *ngIf="paymentMode.invalid && paymentMode.touched">
        Please select a payment mode.
      </div>
    </div>

    <!-- Place Order Button -->
    <button type="submit" class="btn btn-primary" 
            [disabled]="orderForm.invalid || cartItems.length === 0">
      Place Order
    </button>
  </form>
</div>
